    const files = readdirSync(src, { recursive: true, encoding: 'utf8' }).filter((f) => f.endsWith('.ts'));
    for (const f of files) expect(readFileSync(join(src, f), 'utf8'), f).not.toMatch(/from ['"]@zkpassport\//);
  });
});

